    "@context": "https://schema.org",
    "@type": "FAQPage",
    "mainEntity": [
      {
        "@type": "Question",
        "name": "What is 3D point cloud data collection?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "It's the capture of 3D geometry as sets of points, often with color and normals, using depth cameras, stereo, structured light, photogrammetry, or scanners. For robotics, the data trains and evaluates grasping, 3D perception, and scene understanding, and feeds simulation assets."
        }
      },
      {
        "@type": "Question",
        "name": "What's the difference between point cloud and LiDAR data collection?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "LiDAR data collection focuses on long-range scans from moving robots and vehicles for perception, mapping, and localization. Point cloud collection covers near-field and object-level geometry for grasping, digital twins, and simulation assets, using a wider range of 3D sensors."
        }
      },
      {
        "@type": "Question",
        "name": "How do you capture transparent or reflective objects?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "We combine capture methods, use reference geometry from precise scans, and flag unreliable regions rather than filling them. Research such as Google's ClearGrasp shows corrected depth on transparent objects can raise grasp success from 12% to 74%, so honest geometry here matters."
        }
      },
      {
        "@type": "Question",
        "name": "Can you turn scans into simulation-ready assets for Isaac Sim?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Yes. We build USD assets with physics properties, joints, and collision geometry validated against a repeatable standard, as in our Turing program for NVIDIA Isaac Sim."
        }
      },
      {
        "@type": "Question",
        "name": "Which point cloud formats do you deliver?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "PLY, PCD, E57, and LAS or LAZ for clouds, OBJ or GLB for meshes, and USD for simulation assets, with intrinsics, extrinsics, poses, and quality scores included."
        }
      },
      {
        "@type": "Question",
        "name": "Do you also label point clouds?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Yes. Our data annotation team handles 3D segmentation, part labels, bounding boxes, and grasp annotations, working from the same specification as the capture plan."
        }
      }
    ]
  }
